"""Source/target filename conversion commands."""
import os

_PREFIXES = ("run_onchange_", "run_once_", "run_", "private_", "executable_",
             "readonly_", "symlink_", "encrypted_", "exact_", "create_",
             "modify_", "remove_", "once_", "before_", "after_",
             "on-change_", "empty_", "dot_")


def _decode_component(name):
    # Attribute prefixes can be stacked; dot_ is a filename transform.
    while True:
        for prefix in _PREFIXES:
            if name.startswith(prefix):
                name = name[len(prefix):]
                if prefix == "dot_":
                    name = "." + name
                break
        else:
            return name


def source_to_target(path, source, destination):
    source = os.path.abspath(os.path.expanduser(source))
    path = os.path.abspath(os.path.expanduser(path))
    try:
        rel = os.path.relpath(path, source)
    except ValueError:
        raise ValueError(f"{path}: not in {source}")
    if rel == os.pardir or rel.startswith(os.pardir + os.sep):
        raise ValueError(f"{path}: not in {source}")
    if rel == ".":
        raise ValueError(f"{path}: not a valid source path")
    components = rel.split(os.sep)
    if components[-1].endswith(".tmpl"):
        components[-1] = components[-1][:-5]
    result = os.path.join(os.path.abspath(os.path.expanduser(destination)),
                          *(_decode_component(p) for p in components))
    return result


def target_to_source(path, source, destination):
    source = os.path.abspath(os.path.expanduser(source))
    destination = os.path.abspath(os.path.expanduser(destination))
    path = os.path.abspath(os.path.expanduser(path))
    try:
        rel = os.path.relpath(path, destination)
    except ValueError:
        raise ValueError(f"{path}: not in destination directory ({destination})")
    if rel == os.pardir or rel.startswith(os.pardir + os.sep):
        raise ValueError(f"{path}: not in destination directory ({destination})")
    if rel == ".":
        raise ValueError(f"{path}: not managed")
    # Prefer the first matching managed path. Encoding is deterministic for
    # the common filename transforms used by chezmoi.
    source_rel = os.path.join(*(_encode_component(p) for p in rel.split(os.sep)))
    result = os.path.join(source, source_rel)
    if not os.path.lexists(result) and not os.path.lexists(result + ".tmpl"):
        raise ValueError(f"{path}: not managed")
    if not os.path.lexists(result) and os.path.lexists(result + ".tmpl"):
        result += ".tmpl"
    return result


def _encode_component(name):
    if name.startswith("."):
        return "dot_" + name[1:]
    if name.startswith(_PREFIXES):
        return "private_" + name
    return name


def _run(args, fn, source, destination):
    paths = [a for a in args if not a.startswith("-")]
    if not paths:
        # source-path with no targets prints the source directory; target-path
        # with no source paths prints the destination directory.
        return (source if fn is target_to_source else destination) + "\n", "", 0
    out = []
    for path in paths:
        try:
            out.append(fn(path, source, destination))
        except ValueError as e:
            return "", "chezmoi: " + str(e) + "\n", 1
    return "".join(p + "\n" for p in out), "", 0


def run_source_path(args, source, destination):
    return _run(args, target_to_source, source, destination)


def run_target_path(args, source, destination):
    return _run(args, source_to_target, source, destination)

