"""Add destination files to chezmoi's encoded source state."""
import os
import shutil
import stat


def _encode(rel, mode, is_link=False, exact=False):
    parts = rel.split(os.sep)
    out = []
    for part in parts:
        if part.startswith('.'):
            part = 'dot_' + part[1:]
        out.append(part)
    name = os.path.join(*out)
    if exact:
        name = 'exact_' + name
    elif is_link:
        name = 'symlink_' + name
    elif mode & 0o111:
        name = 'executable_' + name
    elif (mode & 0o077) == 0:
        name = 'private_' + name
    elif not mode & 0o222:
        name = 'readonly_' + name
    return name


def run(source, destination, args=None, dry_run=False):
    """Return (stdout, stderr, status)."""
    args = list(args or [])
    recursive, template, exact, new, create, quiet = True, False, False, False, False, False
    targets = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-r', '--recursive'):
            recursive = True
        elif a == '--no-recursive':
            recursive = False
        elif a in ('-T', '--template'):
            template = True
        elif a == '--exact':
            exact = True
        elif a == '--new':
            new = True
        elif a == '--create':
            create = True
        elif a in ('-q', '--quiet'):
            quiet = True
        elif a in ('-h', '--help'):
            return '', '', 0
        elif a in ('-i', '--include', '-x', '--exclude', '--secrets'):
            i += 1
        elif a.startswith(('--include=', '--exclude=', '--secrets=')):
            pass
        elif a.startswith('-'):
            return '', f'chezmoi: unknown flag: {a}\n', 1
        else:
            targets.append(a)
        i += 1
    src = os.path.abspath(os.path.expanduser(source))
    dst = os.path.abspath(os.path.expanduser(destination))
    if not os.path.isdir(src):
        try:
            os.makedirs(src, exist_ok=True)
        except OSError as e:
            return '', f'chezmoi: {e}\n', 1
    if not targets:
        return '', 'chezmoi: add requires at least one target\n', 1
    for target in targets:
        path = os.path.abspath(os.path.expanduser(target))
        if not os.path.lexists(path) and new:
            try:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, 'ab').close()
            except OSError as e:
                return '', f'chezmoi: {e}\n', 1
        try:
            rel = os.path.relpath(path, dst)
        except ValueError:
            return '', f'chezmoi: {path}: not in destination directory ({dst})\n', 1
        if rel == '..' or rel.startswith('..' + os.sep):
            return '', f'chezmoi: {path}: not in destination directory ({dst})\n', 1
        if not os.path.lexists(path) and create:
            if not dry_run:
                outpath = os.path.join(src, 'create_' + _encode(rel, 0o644))
                try:
                    os.makedirs(os.path.dirname(outpath), exist_ok=True)
                    open(outpath, 'ab').close()
                except OSError as e:
                    return '', f'chezmoi: {e}\n', 1
            continue
        if not os.path.lexists(path):
            return '', f'chezmoi: stat {path}: no such file or directory\n', 1
        if os.path.isdir(path) and not os.path.islink(path):
            if exact:
                outrel = _encode(rel, os.stat(path).st_mode, exact=True)
                outpath = os.path.join(src, outrel)
                if not dry_run:
                    os.makedirs(os.path.dirname(outpath), exist_ok=True)
                    os.makedirs(outpath, exist_ok=True)
            elif recursive:
                for root, dirs, files in os.walk(path, followlinks=False):
                    dirs.sort(); files.sort()
                    for name in files + [d for d in dirs if os.path.islink(os.path.join(root, d))]:
                        child = os.path.join(root, name)
                        childrel = os.path.relpath(child, dst)
                        error = _copy_one(child, childrel, src, template, dry_run)
                        if error:
                            return '', error, 1
            continue
        error = _copy_one(path, rel, src, template, dry_run, create=create)
        if error:
            return '', error, 1
    return '', '', 0


def _copy_one(path, rel, source, template, dry_run, create=False):
    link = os.path.islink(path)
    try:
        mode = os.lstat(path).st_mode
